def merge_intervals(xs: list[tuple[int, int]]) -> list[tuple[int, int]]:
    """Merge overlapping closed intervals; return them sorted by start. Touching intervals (1,2),(2,3) merge."""

    # Sort intervals based on their start time
    xs.sort(key=lambda x: x[0])

    merged = []
    for interval in xs:
        # If merged list is empty or ends before current interval starts, append
        if not merged or merged[-1][1] < interval[0]:
            merged.append(interval)
        else:
            # Otherwise, there's an overlap, so we merge these
            merged[-1] = (merged[-1][0], max(merged[-1][1], interval[1]))

    return merged

